package com.rtsbuilding.rtsbuilding.client.rendering.builder;
import com.rtsbuilding.rtsbuilding.Config;import com.rtsbuilding.rtsbuilding.client.controller.ClientRtsController;import com.rtsbuilding.rtsbuilding.client.screen.shape.ShapeDataRecords;import com.rtsbuilding.rtsbuilding.server.workflow.model.RtsWorkflowStatus;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiScreen;import com.rtsbuilding.rtsbuilding.platform.render.BufferBuilder;import com.rtsbuilding.rtsbuilding.platform.math.AxisAlignedBB;import com.rtsbuilding.rtsbuilding.platform.math.BlockPos;import java.lang.reflect.Method;import java.util.*;
/** 1.12 形状建造/破坏幽灵的状态分派入口。 */
public final class ShapeGhostRenderer{
 private static float smooth;private static long smoothAt;private static int smoothKey;private static final long FADE=180;private static int completedKey;private static long fadeAt;private ShapeGhostRenderer(){}
 public static void renderShapeGhostPreview(Minecraft mc,BufferBuilder lines,BufferBuilder fills){GuiScreen screen=mc==null?null:mc.currentScreen;if(screen==null||!"BuilderScreen".equals(screen.getClass().getSimpleName()))return;boolean saw=false;try{@SuppressWarnings("unchecked")List<ShapeDataRecords.GhostPreview>confirmed=(List<ShapeDataRecords.GhostPreview>)screen.getClass().getMethod("getConfirmedRangeDestroyPreviews").invoke(screen);if(confirmed!=null)for(ShapeDataRecords.GhostPreview p:confirmed){saw|=confirmed(p);renderOne(mc,p,lines,fills,null);}ShapeDataRecords.GhostPreview current=(ShapeDataRecords.GhostPreview)screen.getClass().getMethod("getShapeGhostPreview").invoke(screen);Object controller=screen.getClass().getMethod("getShapeController").invoke(screen);AxisAlignedBB box=(AxisAlignedBB)controller.getClass().getMethod("shapeSelectionRenderAabb").invoke(controller);saw|=confirmed(current);renderOne(mc,current,lines,fills,box);}catch(ReflectiveOperationException ignored){return;}if(!saw)MergedSkeletonRenderer.clearCache();}
 public static void markDestroyed(BlockPos p){MergedSkeletonRenderer.markDestroyed(p);}
 private static void renderOne(Minecraft mc,ShapeDataRecords.GhostPreview p,BufferBuilder l,BufferBuilder f,AxisAlignedBB box){p=clamp(p);if(p==null)return;if(!p.chainDestroyPreview()&&empty(p.blocks())&&empty(p.emptyBlocks()))return;ClientRtsController c=ClientRtsController.get();if(p.destructive()&&p.confirmedWorkArea()){Visual v=visual(c,p);if(v.alpha<=0)return;if(Config.isRangeDestroySkeletonEnabled()){MergedSkeletonRenderer.renderConfirmedDestroyWorkArea(p,l,f,v.progress,v.alpha);}else DestructiveGhostRenderer.render(p,l,f,v.progress,v.alpha);return;}if(p.chainDestroyPreview()){UltimineGhostRenderer.render(p,l,f,smoothedDestroyProgress(c,p));return;}if(p.destructive()){DestructiveGhostRenderer.render(p,l,f,0,1,box);return;}BuildGhostRenderer.render(mc,p,l,f,shouldRenderPlacementBlockGhost(p,Config.isPlacementBlockGhostPreviewEnabled()),shouldRenderPlacementWireframe(p,Config.isPlacementWireframePreviewEnabled()));}
 static boolean shouldRenderPlacementBlockGhost(ShapeDataRecords.GhostPreview p,boolean enabled){return enabled&&p!=null&&!empty(p.blocks());}static boolean shouldRenderPlacementWireframe(ShapeDataRecords.GhostPreview p){return shouldRenderPlacementWireframe(p,Config.isPlacementWireframePreviewEnabled());}static boolean shouldRenderPlacementWireframe(ShapeDataRecords.GhostPreview p,boolean enabled){return enabled&&p!=null&&!empty(p.blocks());}
 static float smoothedDestroyProgress(ClientRtsController c,ShapeDataRecords.GhostPreview p){int k=key(p);float target=raw(c,p);long now=System.currentTimeMillis();if(k!=smoothKey||smoothAt==0){smoothKey=k;smoothAt=now;smooth=target;return smooth;}float dt=Math.min(.1F,Math.max(0,(now-smoothAt)/1000F));smoothAt=now;float max=(target>smooth?4.5F:1.8F)*dt;if(Math.abs(target-smooth)<=max)smooth=target;else smooth+=Math.signum(target-smooth)*max;return clamp(smooth);}
 private static float raw(ClientRtsController c,ShapeDataRecords.GhostPreview p){if(c==null)return 0;BlockPos q=c.getMineProgressPos();float mining=q!=null&&previewContains(p,q)&&c.getMineProgressStage()>=0?(Math.min(9,c.getMineProgressStage())+1)/10F:0;RtsWorkflowStatus w=c.findActiveDestroyWorkflow();return w!=null&&w.totalBlocks()>0?clamp((float)w.completedBlocks()/w.totalBlocks()):mining;}
 static boolean hasStartedDestroyBatch(ClientRtsController c,ShapeDataRecords.GhostPreview p){RtsWorkflowStatus w=c==null?null:c.findActiveDestroyWorkflow();return c!=null&&previewContains(p,c.getMineProgressPos())&&w!=null&&w.totalBlocks()>0&&w.completedBlocks()>0;}
 static boolean previewContains(ShapeDataRecords.GhostPreview p,BlockPos q){return p!=null&&q!=null&&(contains(p.blocks(),q)||contains(p.emptyBlocks(),q));}
 private static Visual visual(ClientRtsController c,ShapeDataRecords.GhostPreview p){int k=key(p);RtsWorkflowStatus w=c==null?null:c.findActiveDestroyWorkflow();boolean done=w!=null&&w.totalBlocks()>0&&w.completedBlocks()>=w.totalBlocks()&&previewContains(p,c.getMineProgressPos());long now=System.currentTimeMillis();if(done){if(completedKey!=k){completedKey=k;fadeAt=c.getMineProgressCompletedAtMs()>0?c.getMineProgressCompletedAtMs():now;}return new Visual(1,clamp(1-(now-fadeAt)/(float)FADE));}return new Visual(smoothedDestroyProgress(c,p),1);}
 private static ShapeDataRecords.GhostPreview clamp(ShapeDataRecords.GhostPreview p){if(p==null)return null;ClientRtsController c=ClientRtsController.get();if(!c.hasBounds())return p;List<BlockPos>a=filter(p.blocks(),c.getAnchorX(),c.getAnchorZ(),c.getMaxRadius()),b=filter(p.emptyBlocks(),c.getAnchorX(),c.getAnchorZ(),c.getMaxRadius());if(a.isEmpty()&&b.isEmpty())return null;if(a==p.blocks()&&b==p.emptyBlocks())return p;return new ShapeDataRecords.GhostPreview(a,p.readyConfirm(),p.destructive(),b,p.chainDestroyPreview(),p.confirmedWorkArea());}
 private static List<BlockPos>filter(List<BlockPos>x,double ax,double az,double r){if(x==null||x.isEmpty())return x==null?Collections.<BlockPos>emptyList():x;int minX=(int)Math.floor(ax-r),maxX=(int)Math.ceil(ax+r)-1,minZ=(int)Math.floor(az-r),maxZ=(int)Math.ceil(az+r)-1;List<BlockPos>o=new ArrayList<BlockPos>();for(BlockPos p:x)if(p!=null&&p.getX()>=minX&&p.getX()<=maxX&&p.getZ()>=minZ&&p.getZ()<=maxZ)o.add(p);return o.size()==x.size()?x:o;}
 private static boolean confirmed(ShapeDataRecords.GhostPreview p){return p!=null&&p.destructive()&&p.confirmedWorkArea();}private static boolean empty(List<?>l){return l==null||l.isEmpty();}private static boolean contains(List<BlockPos>l,BlockPos p){return l!=null&&l.contains(p);}private static float clamp(float v){return Math.max(0,Math.min(1,v));}private static int key(ShapeDataRecords.GhostPreview p){int h=1;if(p!=null){if(p.blocks()!=null)for(BlockPos q:p.blocks())h=31*h+(q==null?0:q.hashCode());h=31*h+(p.chainDestroyPreview()?1:0);h=31*h+(p.confirmedWorkArea()?1:0);}return h;}private static final class Visual{final float progress,alpha;Visual(float p,float a){progress=p;alpha=a;}}
}
